    for pkg_name, vulns in unpinned_packages.items():
        vuln_count = len(vulns)
        msg = f'Warning: {vuln_count} known {"vulnerability" if vuln_count == 1 else "vulnerabilities"} match the {pkg_name} versions that could be'
        result.append(format_long_text(msg, columns=columns, start_line_decorator='', end_line_decorator=''))

    return result
